private void ModifyDataAndGrid()
{
    if (dtbData == null || dtbQuestion == null)
        return;

    dictQuestionColumn.Clear();

    int groupIndex = 1;
    int i = 1;
    foreach(DataRow drwQuestion in dtbQuestion.Rows)
    {
        // Thêm Value Band

        string strGroupName ="gbQuestion" + groupIndex;
        GridBand gbQuestion = gvData.Bands[strGroupName];
        if (gbQuestion == null)
        {
            gbQuestion = new GridBand();                    
            gbQuestion.AppearanceHeader.Options.UseFont = true;
            gbQuestion.AppearanceHeader.Options.UseTextOptions = true;
            gbQuestion.AppearanceHeader.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Center;
            gbQuestion.AppearanceHeader.Font = new Font("Tahoma", 8.25F, FontStyle.Bold);
            gbQuestion.Name = strGroupName;                    
            gvData.Bands.Add(gbQuestion);                    
        }

        gbQuestion.Caption = "Câu " + groupIndex.ToString(); // tạm thời là index câu, sau này dùng phân đoạn, phần, nhóm cho đẹp
        gbQuestion.Visible = true;
        groupIndex++;


        string strCol = "Value_" + i.ToString();

        if (!Convert.IsDBNull(drwQuestion["QuestionID"]))
        {
            int intQuestionID = Convert.ToInt32(drwQuestion["QuestionID"]);
            if (!dictQuestionColumn.ContainsKey(intQuestionID))
                dictQuestionColumn.Add(intQuestionID, strCol);
        }

        // Tạo cột vào dtbData
        if (!dtbData.Columns.Contains(strCol))
            dtbData.Columns.Add(strCol, typeof(string));


        // Tạo cột vào grid
        // col
        BandedGridColumn gcolValue = gvData.Columns[strCol];
        if (gcolValue == null)
        {
            gcolValue =  new BandedGridColumn();                    
            gcolValue.FieldName = strCol;
            gcolValue.Name = "gcol" + strCol;
            gcolValue.Visible = true;
            gcolValue.AppearanceHeader.Options.UseTextOptions = true;
            gcolValue.AppearanceHeader.TextOptions.WordWrap = DevExpress.Utils.WordWrap.Wrap;                    
            //gcolValue.AppearanceHeader.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Center;

            // cho no xuong hang
            Control.RepositoryItemMyMemoEdit colEdit = new Control.RepositoryItemMyMemoEdit();
            gcolValue.ColumnEdit = colEdit;

            gvData.Columns.Add(gcolValue);
        }

        if (gcolValue.OwnerBand != gbQuestion)
            gbQuestion.Columns.Add(gcolValue);

        // gán lại tiêu đề
        gcolValue.Visible = true;
        gcolValue.Caption = drwQuestion["QuestionName"].ToString();

        i++;
    }

    // Ẩn các cột thừa khi đổi dữ liệu tìm kiếm
    foreach (BandedGridColumn gcol in gvData.Columns)
    {
        if (gcol.FieldName != null && gcol.FieldName.Contains("Value_"))
        {
            if (Convert.ToInt32(gcol.FieldName.Replace("Value_", "")) > dtbQuestion.Rows.Count)
            {
                gcol.Visible = false;
                if (gcol.OwnerBand != null)
                    gcol.OwnerBand.Visible = false;
            }
        }
    }
}

private void FillData()
{
    if (dtbData == null || dtbDetail == null)
        return;
    if (!dtbData.Columns.Contains("DoneID") || !dtbDetail.Columns.Contains("DoneID") || !dtbDetail.Columns.Contains("QuestionID"))
        return;

    foreach (DataRow drw in dtbData.Rows)
    {
        if (Convert.IsDBNull(drw["DoneID"]))
            continue;

        DataRow[] rows = dtbDetail.Select(String.Format("DoneID = {0}", drw["DoneID"]));
        foreach (DataRow drwDetail in rows)
        {
            if (Convert.IsDBNull(drwDetail["QuestionID"]))
                continue;

            int intQuestionID = Convert.ToInt32(drwDetail["QuestionID"]);
            if (!dictQuestionColumn.ContainsKey(intQuestionID))
                continue;

            string strCol = dictQuestionColumn[intQuestionID];
            if (!dtbData.Columns.Contains(strCol))
                continue;

            drw[strCol] = GetAnswerText(drwDetail);
        }
    }
}

private string GetAnswerText(DataRow drwDetail)
{
    if (dtbDetail.Columns.Contains("DoAnswerContent") && !Convert.IsDBNull(drwDetail["DoAnswerContent"]))
    {
        string strContent = Convert.ToString(drwDetail["DoAnswerContent"]).Trim();
        if (strContent != "")
            return strContent;
    }

    if (dtbDetail.Columns.Contains("DoMark") && !Convert.IsDBNull(drwDetail["DoMark"]))
        return Convert.ToString(drwDetail["DoMark"]);

    if (dtbDetail.Columns.Contains("DoAnswerIndex") && !Convert.IsDBNull(drwDetail["DoAnswerIndex"]))
        return Convert.ToString(drwDetail["DoAnswerIndex"]);

    return "";
}

