private string GetAnswerText(DataRow drwDetail)
{
    if (dtbDetail.Columns.Contains("DoAnswerContent") && !Convert.IsDBNull(drwDetail["DoAnswerContent"]))
    {
        string strContent = NormalizeAnswerText(Convert.ToString(drwDetail["DoAnswerContent"]));
        if (strContent != "")
            return strContent;
    }

    if (dtbDetail.Columns.Contains("DoMark") && !Convert.IsDBNull(drwDetail["DoMark"]))
        return NormalizeAnswerText(Convert.ToString(drwDetail["DoMark"]));

    if (dtbDetail.Columns.Contains("DoAnswerIndex") && !Convert.IsDBNull(drwDetail["DoAnswerIndex"]))
        return NormalizeAnswerText(Convert.ToString(drwDetail["DoAnswerIndex"]));

    return "";
}

/// <summary>
/// POL_DoneDetail lưu đáp án dạng ;4; (ngăn cách bằng dấu ;).
/// Cắt ; đầu/cuối để lưới chỉ hiện 4.
/// </summary>
private string NormalizeAnswerText(string strValue)
{
    if (strValue == null)
        return "";

    string strResult = strValue.Trim();
    strResult = strResult.Trim(';');
    strResult = strResult.Trim();
    return strResult;
}

